import { useEffect, useRef, useState } from 'react';
import type HanziWriterType from 'hanzi-writer';
import type { CharacterJson } from 'hanzi-writer';
import { useI18n } from '../i18n/LocaleContext';
import { Button, cx } from './ui';

/*
 * Chinese stroke-order animation and writing practice, built on Hanzi Writer (MIT,
 * https://github.com/chanind/hanzi-writer).
 *
 * Character data is bundled OFFLINE: src/courses/zh/strokes/data.json is generated by `npm run strokes`
 * (scripts/build-strokes.mjs) from the `hanzi-writer-data` package, which comes from Make Me a Hanzi
 * (https://github.com/skishore/makemeahanzi). Its stroke graphics are derived from fonts by Arphic Technology
 * and are licensed under the Arphic Public License. The JSON and the Hanzi Writer library are loaded lazily
 * with dynamic import(), so neither is part of the main bundle.
 */

type StrokeData = Record<string, CharacterJson>;
interface Engine { HanziWriter: typeof HanziWriterType; data: StrokeData }

let enginePromise: Promise<Engine> | null = null;
function loadEngine(): Promise<Engine> {
  enginePromise ??= Promise.all([import('hanzi-writer'), import('../courses/zh/strokes/data.json')])
    .then(([hw, json]) => ({ HanziWriter: hw.default, data: json.default as unknown as StrokeData }))
    .catch((e: unknown) => { enginePromise = null; throw e; });
  return enginePromise;
}

const SIZE = 160;
const COLORS = { strokeColor: '#2f3542', outlineColor: '#e2e8f0', drawingColor: '#0ea5e9', highlightColor: '#f59e0b', radicalColor: null };

/** Stroke-order cards for a list of characters (duplicates and non-Han characters are skipped). */
export function StrokeOrder({ chars }: { chars: string[] }) {
  const { t } = useI18n();
  const [engine, setEngine] = useState<Engine | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let alive = true;
    loadEngine().then((e) => { if (alive) setEngine(e); }, () => { if (alive) setFailed(true); });
    return () => { alive = false; };
  }, []);

  const list = [...new Set(chars.flatMap((c) => [...c]).filter((c) => /\p{Script=Han}/u.test(c)))];

  return (
    <div>
      {failed && <p role="alert" className="mb-2 text-sm text-rose-600">{t('strokes.loadError')}</p>}
      {!engine && !failed && <p className="mb-2 text-sm text-muted" aria-live="polite">{t('strokes.loading')}</p>}
      <div className="grid grid-cols-1 gap-3 min-[380px]:grid-cols-2 lg:grid-cols-3">
        {list.map((c) => <CharCard key={c} char={c} engine={engine} />)}
      </div>
      <p className="mt-2 text-xs text-muted">{t('strokes.credit')}</p>
    </div>
  );
}

type Mode = 'idle' | 'animating' | 'quiz' | 'done';

function CharCard({ char, engine }: { char: string; engine: Engine | null }) {
  const { t } = useI18n();
  const target = useRef<HTMLDivElement>(null);
  const writer = useRef<HanziWriterType | null>(null);
  const [mode, setMode] = useState<Mode>('idle');
  const [done, setDone] = useState(0);
  const [mistakes, setMistakes] = useState(0);

  const data = engine?.data[char];
  const total = data?.strokes.length ?? 0;

  useEffect(() => {
    const el = target.current;
    if (!engine || !data || !el) return;
    const w = engine.HanziWriter.create(el, char, {
      width: SIZE, height: SIZE, padding: 8, ...COLORS,
      showOutline: true, showCharacter: true,
      strokeAnimationSpeed: 1, delayBetweenStrokes: 300,
      charDataLoader: () => data,
    });
    writer.current = w;
    return () => {
      w.cancelQuiz();
      writer.current = null;
      el.innerHTML = '';
    };
  }, [engine, data, char]);

  const animate = () => {
    const w = writer.current;
    if (!w) return;
    w.cancelQuiz();
    setMode('animating');
    void w.showCharacter({ duration: 0 });
    void w.animateCharacter({ onComplete: () => setMode((m) => (m === 'animating' ? 'idle' : m)) });
  };

  const practice = () => {
    const w = writer.current;
    if (!w) return;
    setMode('quiz');
    setDone(0);
    setMistakes(0);
    void w.quiz({
      showHintAfterMisses: 3,
      onCorrectStroke: (s) => setDone(s.strokeNum + 1),
      onMistake: (s) => setMistakes(s.totalMistakes),
      onComplete: ({ totalMistakes }) => { setMistakes(totalMistakes); setDone(total); setMode('done'); },
    });
  };

  const reset = () => {
    const w = writer.current;
    if (!w) return;
    w.cancelQuiz();
    setMode('idle');
    setDone(0);
    setMistakes(0);
    void w.showOutline({ duration: 0 });
    void w.showCharacter({ duration: 0 });
  };

  const missing = !!engine && !data;
  const ready = !!engine && !!data;

  let status = '';
  if (mode === 'quiz') status = `${t('strokes.progress', { done, total })} · ${t('strokes.practiceHint')}`;
  else if (mode === 'done') status = mistakes === 0 ? t('strokes.perfect') : t('strokes.done', { count: mistakes });

  return (
    <div className="rounded-xl border border-line bg-white p-3">
      <div className="flex items-baseline justify-between gap-2">
        <span className="font-zh text-xl" lang="zh-CN">{char}</span>
        {ready && <span className="text-xs text-muted">{t('strokes.strokeCount', { count: total })}</span>}
      </div>
      <div className="relative mx-auto mt-2" style={{ width: SIZE, height: SIZE }}>
        <GridBackground />
        {ready ? (
          <div
            ref={target}
            role="img"
            aria-label={mode === 'quiz' ? t('strokes.canvasLabel', { char }) : t('strokes.charLabel', { char })}
            className={cx('relative', mode === 'quiz' && 'cursor-crosshair')}
            style={{ width: SIZE, height: SIZE, touchAction: mode === 'quiz' ? 'none' : undefined }}
          />
        ) : (
          <div className="relative flex h-full w-full items-center justify-center font-zh text-8xl text-stone-700" lang="zh-CN" aria-label={t('strokes.charLabel', { char })} role="img">
            {char}
          </div>
        )}
      </div>
      {missing && <p className="mt-2 text-xs text-muted">{t('strokes.missing', { char })}</p>}
      {ready && (
        <>
          <div className="mt-2 flex flex-wrap justify-center gap-1.5">
            <Button variant="secondary" className="px-3 py-1.5" onClick={animate}>{t('strokes.animate')}</Button>
            <Button variant="secondary" className="px-3 py-1.5" onClick={practice} aria-pressed={mode === 'quiz'}>{t('strokes.practice')}</Button>
            <Button variant="ghost" className="px-3 py-1.5" onClick={reset}>{t('strokes.reset')}</Button>
          </div>
          <p className="mt-1 min-h-[1.25rem] text-center text-xs text-muted" aria-live="polite">{status}</p>
        </>
      )}
    </div>
  );
}

/** 米字格 practice grid behind the character. */
function GridBackground() {
  return (
    <svg className="pointer-events-none absolute inset-0 text-stone-200" width={SIZE} height={SIZE} aria-hidden="true">
      <rect x="0.5" y="0.5" width={SIZE - 1} height={SIZE - 1} fill="none" stroke="currentColor" />
      <g stroke="currentColor" strokeDasharray="4 4">
        <line x1="0" y1={SIZE / 2} x2={SIZE} y2={SIZE / 2} />
        <line x1={SIZE / 2} y1="0" x2={SIZE / 2} y2={SIZE} />
        <line x1="0" y1="0" x2={SIZE} y2={SIZE} />
        <line x1={SIZE} y1="0" x2="0" y2={SIZE} />
      </g>
    </svg>
  );
}
